package com.girish.jdbc.util;
import java.math.BigDecimal;import java.time.LocalDate;import java.time.format.DateTimeParseException;import java.util.Scanner;import java.util.function.Function;
public final class Input {private Input(){} public static String text(Scanner s,String p){while(true){System.out.print(p);String v=s.nextLine().trim();if(!v.isEmpty())return v;System.out.println("Value is required.");}} public static int integer(Scanner s,String p){return parse(s,p,Integer::parseInt);} public static BigDecimal decimal(Scanner s,String p){return parse(s,p,BigDecimal::new);} public static LocalDate date(Scanner s,String p){return parse(s,p,LocalDate::parse);} private static <T>T parse(Scanner s,String p,Function<String,T> f){while(true){try{System.out.print(p);return f.apply(s.nextLine().trim());}catch(NumberFormatException|DateTimeParseException e){System.out.println("Invalid value. Try again.");}}}}
